  "Nguyen dynasty": {capital:"Hue",founder:"Gia Long (Nguyen Anh)",predecessor:"Nguyen lords; Tay Son dynasty",successor:"Empire of Vietnam (1945); Democratic Republic of Vietnam"},
  "British Raj": {capital:"Calcutta; later New Delhi (from 1911/1931); Simla in summer",founder:"British Crown (Government of India Act 1858); first viceroy Lord Canning",predecessor:"Company rule in India",successor:"Dominion of India; Dominion of Pakistan"},
  "French Indochina": {capital:"Saigon; Hanoi from 1902",founder:"French Third Republic (decree of 17 October 1887)",predecessor:"French Cochinchina; Nguyen dynasty; French protectorate of Cambodia",successor:"Democratic Republic of Vietnam; State of Vietnam; Kingdom of Laos; Kingdom of Cambodia"},
  "Indonesia": {capital:"Jakarta (Yogyakarta 1946–1949); Nusantara under construction",founder:"Sukarno and Mohammad Hatta",predecessor:"Dutch East Indies"},
  "Myanmar": {capital:"Rangoon (Yangon); Naypyidaw from 2005–2006",founder:"Aung San (negotiated independence); U Nu, first prime minister",predecessor:"British Burma"},
  "United State of Rajasthan": {capital:"Kota (March 1948); Udaipur (April 1948); Jaipur from March 1949",founder:"Vallabhbhai Patel and V.P. Menon of the States Ministry, with the rulers of Rajputana",predecessor:"Princely states of Rajputana (Udaipur, Jaipur, Jodhpur, Bikaner and others)",successor:"Rajasthan (state of India)"},
  "Republic of India": {capital:"New Delhi",founder:"Jawaharlal Nehru, B.R. Ambedkar and the Constituent Assembly",predecessor:"Dominion of India"},
  "Malaysia": {capital:"Kuala Lumpur (administrative centre at Putrajaya from 1999)",founder:"Tunku Abdul Rahman",predecessor:"Federation of Malaya; Crown Colonies of Singapore, North Borneo and Sarawak"},
