  "Swazi Kingdom": {capital:"Royal villages of the Ezulwini valley; later Lobamba (royal and legislative) and Mbabane (administrative)",founder:"Ngwane III; Sobhuza I",predecessor:"Dlamini chiefdom",successor:"Kingdom of Eswatini (continuing)"},
