  "South African Republic": {capital:"Potchefstroom; Pretoria from 1860",founder:"Marthinus Wessel Pretorius",predecessor:"Potchefstroom Republic and the other Voortrekker communities north of the Vaal",successor:"Transvaal Colony"},
  "Orange Free State": {capital:"Bloemfontein",founder:"Josias Hoffman (first president)",predecessor:"Orange River Sovereignty",successor:"Orange River Colony"},
  "Sultanate of Zanzibar": {capital:"Zanzibar City (Stone Town)",founder:"Majid bin Said",predecessor:"Omani Empire",successor:"People’s Republic of Zanzibar"},
